                                                                                                                                                                                                                                                                                                                                                                                                                                          
  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TENANT_USER_GROUP_ASSO_V" ("USER_GROUP_ASSO_ID", "USER_GROUP_ID", "TENANT_ID", "CREATION_DATE", "USER_GROUP_CODE", "ORG_GROUP_CODE", "USER_GROUP_ASSO_CODE", "BIND_EXT_ORG_ID", "BIND_EXT_ORG_NAME", "CODE_NAME", "EXT_USER_ID", "SYNC_USER_ID", "UNIONID", "TITLE", "NAME", "AVATAR", "STATE_CODE", "MOBILE", "JOB_NUMBER", "EMAIL", "FAB_ID", "FAB_NAME", "BASE_DEPT_ID") AS     
  select ug.USER_GROUP_ASSO_ID,                                                                                                                                                                                                                                                                                                                                                                                                           
       ug.USER_GROUP_ID,                                                                                                                                                                                                                                                                                                                                                                                                                  
       ug.TENANT_ID,                                                                                                                                                                                                                                                                                                                                                                                                                      
       ug.CREATION_DATE,                                                                                                                                                                                                                                                                                                                                                                                                                  
       ug.USER_GROUP_CODE,                                                                                                                                                                                                                                                                                                                                                                                                                
       ug.ORG_GROUP_CODE,                                                                                                                                                                                                                                                                                                                                                                                                                 
       ug.USER_GROUP_ASSO_CODE,                                                                                                                                                                                                                                                                                                                                                                                                           
       ug.BIND_EXT_ORG_ID,                                                                                                                                                                                                                                                                                                                                                                                                                
       SELECT_DEPT_NAME(ug.BIND_EXT_ORG_ID) as BIND_EXT_ORG_NAME,                                                                                                                                                                                                                                                                                                                                                                         
       u.NAME                               as CODE_NAME,                                                                                                                                                                                                                                                                                                                                                                                 
       main.USER_ID                         as EXT_USER_ID,                                                                                                                                                                                                                                                                                                                                                                               
       main.EXTRA_USER_ID                   as SYNC_USER_ID,                                                                                                                                                                                                                                                                                                                                                                              
       main.UNION_ID                        as UNIONID,                                                                                                                                                                                                                                                                                                                                                                                   
       main.TITLE,                                                                                                                                                                                                                                                                                                                                                                                                                        
       main.NAME,                                                                                                                                                                                                                                                                                                                                                                                                                         
       main.AVATAR,                                                                                                                                                                                                                                                                                                                                                                                                                       
       main.STATE_CODE,                                                                                                                                                                                                                                                                                                                                                                                                                   
       main.MOBILE,                                                                                                                                                                                                                                                                                                                                                                                                                       
       main.JOB_NUMBER,                                                                                                                                                                                                                                                                                                                                                                                                                   
       main.EMAIL,                                                                                                                                                                                                                                                                                                                                                                                                                        
       u.FAB_ID,                                                                                                                                                                                                                                                                                                                                                                                                                          
       ff.NAME                              as FAB_NAME,                                                                                                                                                                                                                                                                                                                                                                                  
       ug.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                                                    
from TENANT_USER_GROUP_ASSO ug                                                                                                                                                                                                                                                                                                                                                                                                            
         left join MPF.SHARE_OPS_USER_INFO_V main                                                                                                                                                                                                                                                                                                                                                                                         
                   on ug.EXT_USER_ID = main.USER_ID and main.IS_LEAVE = 0 and ug.BASE_DEPT_ID = main.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                         
         left join TENANT_USER_GROUP u on ug.USER_GROUP_ID = u.USER_GROUP_ID                                                                                                                                                                                                                                                                                                                                                              
         left join FND_FAB ff on u.FAB_ID = ff.FAB_ID                                                                                                                                                                                                                                                                                                                                                                                     
where main.MAIN_DEPT_ORDER=0;                                                                                                                                                                                                                                                                                                                                                                                                             

